      setSelectedNoteId(note.id)
      setIsEditing(true)
    }, [])

    const handleSelectNote = React.useCallback(async (note: NoteViewModel | null) => {
      await flushIfEditing()
      setSelectedNoteId(note?.id ?? '')
      setIsEditing(false)
    }, [flushIfEditing])

